`timescale 1ns/1ps


// GPU Fragment Writer

// Packs adjacent 32-bit pixels from one rasterizer lane group into aligned
// 64-bit framebuffer words. A group is committed as one AXI write burst.
// The input lane coordinates must describe adjacent X positions on one row,
// as generated by gpu_triangle_rasterizer.v.

module gpu_fragment_writer #(
    parameter integer XLEN = 64,
    parameter integer LANES = 1,
    parameter integer MAX_BURST = 16
)(
    input clk_i,
    input rst_i,

    input fragment_valid_i,
    output fragment_ready_o,
    input [LANES-1:0] fragment_mask_i,
    input [LANES*16-1:0] fragment_x_i,
    input [LANES*16-1:0] fragment_y_i,
    input [LANES*32-1:0] fragment_color_i,

    input [XLEN-1:0] framebuffer_base_i,
    input [31:0] framebuffer_stride_i,
    input [15:0] framebuffer_width_i,
    input [15:0] framebuffer_height_i,

    output busy_o,
    output reg done_o,
    output reg error_o,

    // Write client interface. Connect to gpu.v auxiliary write client.
    output wr_start_o,
    output [XLEN-1:0] wr_addr_o,
    output [7:0] wr_beats_o,
    input wr_start_ready_i,
    output wr_valid_o,
    output [63:0] wr_data_o,
    output [7:0] wr_strb_o,
    input wr_data_ready_i,
    input wr_done_i,
    input wr_error_i
);

    localparam integer MAX_WORDS = (LANES + 2) / 2;
    localparam [1:0] S_IDLE = 2'd0;
    localparam [1:0] S_ISSUE = 2'd1;
    localparam [1:0] S_SEND = 2'd2;
    localparam [1:0] S_WAIT = 2'd3;

    reg [1:0] state;
    reg [63:0] word_buffer [0:MAX_WORDS-1];
    reg [7:0] strb_buffer [0:MAX_WORDS-1];
    reg [7:0] word_count;
    reg [7:0] write_index;
    reg [XLEN-1:0] write_address;

    reg [63:0] packed_words [0:MAX_WORDS-1];
    reg [7:0] packed_strb [0:MAX_WORDS-1];
    reg pack_error;
    reg [7:0] packed_word_count;

    integer pack_lane;
    integer pack_index;
    integer clear_index;
    reg [15:0] pack_x;
    reg [15:0] pack_y;
    reg [31:0] pack_color;
    reg [15:0] first_x;
    reg [15:0] first_y;

    wire [XLEN-1:0] row_offset =
        {{(XLEN-16){1'b0}}, first_y} * {{(XLEN-32){1'b0}}, framebuffer_stride_i};
    wire [XLEN-1:0] first_word_offset =
        {{(XLEN-15){1'b0}}, first_x[15:1]} << 3;

    assign fragment_ready_o = (state == S_IDLE);
    assign busy_o = (state != S_IDLE);
    assign wr_start_o = (state == S_ISSUE);
    assign wr_addr_o = write_address;
    assign wr_beats_o = word_count;
    assign wr_valid_o = (state == S_SEND);
    assign wr_data_o = word_buffer[write_index];
    assign wr_strb_o = strb_buffer[write_index];

    always @* begin
        first_x = fragment_x_i[15:0];
        first_y = fragment_y_i[15:0];
        pack_error = 1'b0;
        packed_word_count = (LANES + first_x[0] + 1) >> 1;

        for (pack_index = 0; pack_index < MAX_WORDS; pack_index = pack_index + 1) begin
            packed_words[pack_index] = 64'd0;
            packed_strb[pack_index] = 8'd0;
        end

        for (pack_lane = 0; pack_lane < LANES; pack_lane = pack_lane + 1) begin
            pack_x = fragment_x_i[pack_lane*16 +: 16];
            pack_y = fragment_y_i[pack_lane*16 +: 16];
            pack_color = fragment_color_i[pack_lane*32 +: 32];
            pack_index = (pack_x >> 1) - (first_x >> 1);

            if (fragment_mask_i[pack_lane]) begin
                if ((pack_x >= framebuffer_width_i) ||
                    (pack_y >= framebuffer_height_i) ||
                    (pack_y != first_y) ||
                    (pack_index < 0) || (pack_index >= MAX_WORDS)) begin
                    pack_error = 1'b1;
                end else if (pack_x[0]) begin
                    packed_words[pack_index][63:32] = pack_color;
                    packed_strb[pack_index][7:4] = 4'hF;
                end else begin
                    packed_words[pack_index][31:0] = pack_color;
                    packed_strb[pack_index][3:0] = 4'hF;
                end
            end
        end
    end

    always @(posedge clk_i) begin
        if (rst_i) begin
            state <= S_IDLE;
            word_count <= 8'd0;
            write_index <= 8'd0;
            write_address <= {XLEN{1'b0}};
            done_o <= 1'b0;
            error_o <= 1'b0;
            for (clear_index = 0; clear_index < MAX_WORDS; clear_index = clear_index + 1) begin
                word_buffer[clear_index] <= 64'd0;
                strb_buffer[clear_index] <= 8'd0;
            end
        end else begin
            done_o <= 1'b0;
            error_o <= 1'b0;

            case (state)
                S_IDLE: begin
                    if (fragment_valid_i && fragment_ready_o && (|fragment_mask_i)) begin
                        if ((framebuffer_base_i[2:0] != 3'b000) ||
                            (framebuffer_stride_i[2:0] != 3'b000) ||
                            (framebuffer_stride_i < ({16'd0, framebuffer_width_i} << 2)) ||
                            (packed_word_count == 0) ||
                            (packed_word_count > MAX_BURST) || pack_error) begin
                            error_o <= 1'b1;
                            done_o <= 1'b1;
                        end else begin
                            for (clear_index = 0; clear_index < MAX_WORDS; clear_index = clear_index + 1) begin
                                word_buffer[clear_index] <= packed_words[clear_index];
                                strb_buffer[clear_index] <= packed_strb[clear_index];
                            end
                            word_count <= packed_word_count;
                            write_index <= 8'd0;
                            write_address <= framebuffer_base_i + row_offset + first_word_offset;
                            state <= S_ISSUE;
                        end
                    end
                end

                S_ISSUE: begin
                    if (wr_start_o && wr_start_ready_i)
                        state <= S_SEND;
                end

                S_SEND: begin
                    if (wr_valid_o && wr_data_ready_i) begin
                        if (write_index == word_count - 1'b1)
                            state <= S_WAIT;
                        else
                            write_index <= write_index + 1'b1;
                    end
                end

                S_WAIT: begin
                    if (wr_done_i) begin
                        if (wr_error_i)
                            error_o <= 1'b1;
                        done_o <= 1'b1;
                        state <= S_IDLE;
                    end
                end

                default: state <= S_IDLE;
            endcase
        end
    end

endmodule